CREATE OR REPLACE FUNCTION public.enforce_paid_chat_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('app.membership_evidence',true)='1' AND NEW.is_auto AND public.has_role(NEW.sender_id,'admin') THEN RETURN NEW; END IF; IF NOT public.can_post_chat(NEW.post_id,NEW.receiver_id) AND NOT public.has_role(NEW.sender_id,'admin') THEN RAISE EXCEPTION 'PAID_CHAT_OR_PRIVATE_PAIR_REQUIRED'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.dispatch_program_requests() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u record; n integer:=0; nid uuid; d date:=(now() AT TIME ZONE 'Asia/Kolkata')::date; BEGIN FOR u IN SELECT p.id FROM public.profiles p WHERE p.bell_activated_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_programs a WHERE a.user_id=p.id) AND public.has_paid_bell(p.id) AND public.can_notify(p.id) AND NOT EXISTS(SELECT 1 FROM public.program_reminders r WHERE r.user_id=p.id AND r.day=d) LIMIT 100 LOOP PERFORM 1 FROM public.profiles WHERE id=u.id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.program_reminders WHERE user_id=u.id AND day=d) THEN CONTINUE; END IF; INSERT INTO public.notifications(user_id,message) VALUES(u.id,'దయచేసి మీ ప్రొఫైల్ నింపండి') RETURNING id INTO nid; IF nid IS NOT NULL THEN INSERT INTO public.program_reminders(user_id,day,notification_id) VALUES(u.id,d,nid) ON CONFLICT DO NOTHING; n:=n+1; END IF; END LOOP; RETURN n; END $$;
CREATE FUNCTION public.notify_exact_saved_return_route() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN IF NEW.module<>'vehicle' OR NEW.kind<>'owner' OR NEW.status<>'active' OR NEW.visible_after>now() OR NEW.trip_date<(now() AT TIME ZONE 'Asia/Kolkata')::date THEN RETURN NEW; END IF; FOR r IN SELECT DISTINCT v.user_id FROM public.vehicle_route_preferences v WHERE v.enabled AND v.user_id<>NEW.user_id AND lower(trim(v.from_place))=lower(trim(NEW.from_place)) AND lower(trim(v.to_place))=lower(trim(NEW.to_place)) AND (v.vehicle_type='' OR lower(trim(v.vehicle_type))=lower(trim(NEW.vehicle_type))) AND (v.capacity_tons IS NULL OR NEW.capacity_tons>=v.capacity_tons) AND public.has_paid_bell(v.user_id) LOOP IF NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=r.user_id AND message='మీ రూట్లో రిటర్న్ బండి ఉంది: '||NEW.from_place||' → '||NEW.to_place AND created_at>now()-interval '1 day') THEN INSERT INTO public.notifications(user_id,message) VALUES(r.user_id,'మీ రూట్లో రిటర్న్ బండి ఉంది: '||NEW.from_place||' → '||NEW.to_place); END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER exact_saved_return_route_notice AFTER INSERT OR UPDATE OF visible_after,status ON public.posts FOR EACH ROW EXECUTE FUNCTION public.notify_exact_saved_return_route();